check('Value bands rank realized revenue into top next middle and long-tail bands', all(x in service for x in ['TOP_10','NEXT_15','MIDDLE_25','LONG_TAIL']) and 'percentile <= 0.10' in service and 'percentile <= 0.25' in service and 'percentile <= 0.50' in service)
check('Top 10 percent concentration is divide-by-zero safe', 'if (rows.isEmpty() || totalRevenue.signum() <= 0) return 0.0' in service and 'Math.ceil(rows.size() * 0.10)' in service)
