check('Frontend documents privacy-safe customer references', 'privacy-safe reference' in page and 'không email/số điện thoại' in page)
check('Frontend types include V56 customer-value contracts', all(x in types for x in ['CustomerValueCinemaV56','CustomerValueRfmSegmentV56','CustomerValueBandV56','CustomerValueRowV56','CustomerValueScorecardV56']))
check('Header exposes V56 Customer Value to Manager/Admin menus', header.count('/admin/customer-value') >= 4)
check('Admin dashboard links V56 Customer Value', '/admin/customer-value' in admin and 'Customer Value V56' in admin)
check('V56 Playwright covers summary RFM bands period and cinema filters', all(x in e2e for x in ['V56 admin reviews privacy-safe realized customer value and RFM by cinema','customer-value-summary-v56','customer-value-rfm-v56','customer-value-bands-v56','customer-value-period-v56','customer-value-cinema-filter-v56']))
ci_match=re.search(r'name:\s*V26-V(\d+) source regression',ci)
check('Main CI extends source regression through V56', bool(ci_match) and int(ci_match.group(1))>=56 and 'verify_v56_customer_value_rfm.py' in ci)
rc_versions=[int(v) for v in re.findall(r'default: "v(\d+)\.0\.0-rc\.1"',rc)]
check('Standalone RC defaults to V56-or-newer and runs V56 gate', bool(rc_versions) and max(rc_versions)>=56 and 'verify_v56_customer_value_rfm.py' in rc)
release_versions=[int(v) for v in re.findall(r'default: "(\d+)\.0\.0"',release)]
check('Stable release defaults to V56-or-newer and runs V56 gate', bool(release_versions) and max(release_versions)>=56 and 'verify_v56_customer_value_rfm.py' in release)
rc_namespaces=[int(v) for v in re.findall(r'cinebooking_v(\d+)_rc_',rc)]
